        uint afterFirst = address(c).balance;
        vm.assume(afterFirst == 0);
        try c.deposit{value: b}() {} catch { return; }
        uint beforeSecond = address(c).balance;
        uint testBalBefore = address(this).balance;
        try c.withdrawAll() {} catch { return; }
        assertTrue(address(this).balance - testBalBefore == b && address(c).balance == beforeSecond - b);
    }

    function testFuzz_run(uint256 a, uint256 b) public {
        _run(a, b);
    }

    receive() external payable {}
