contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint d) public payable {
        require(d > 1 && d <= 10**18);
        // Derive a strictly positive deposit amount that always fits the available balance,
        // so fuzzing never rejects inputs due to a balance precondition.
        uint amt = address(this).balance / (2 * d);
        require(amt > 0);

        c.deposit{value: amt}();
        c.withdrawAll();

        c.deposit{value: amt}();
        uint beforeSecond = address(c).balance;
        uint testBalBefore = address(this).balance;

        c.withdrawAll();

        assert(address(this).balance - testBalBefore == amt && address(c).balance == beforeSecond - amt);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    bool refuseEther;

    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        refuseEther = false;
        c.deposit{value: amount}();
        uint beforeBalance = address(c).balance;

        refuseEther = true;
        bool reverted;
        c.withdrawAll();
        reverted = false;

        refuseEther = false;
        uint afterBalance = address(c).balance;

        assert(!reverted && afterBalance == beforeBalance);
    }

    receive() external payable {
        require(!refuseEther);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint a, uint b) public payable {
        require(a > 0);
        require(b > 0);
        require(address(this).balance >= a + b);

        // A (this contract) deposits a and withdraws it fully.
        c.deposit{value: a}();
        c.withdrawAll();

        // Another depositor (any address, here again via this contract's fresh funds
        // sent to a second test account) is not possible directly; instead we simulate
        // the other depositor using the test contract itself after the withdrawal.
        uint balAfterWithdraw = address(c).balance;

        // After the full cycle the contract should hold zero, so deposit b fresh.
        c.deposit{value: b}();
        uint balBeforeSecond = address(c).balance;
        c.withdrawAll();

        // Because credit was zeroed by the first withdrawAll, the second deposit's
        // funds were already fully withdrawn: the contract must now be empty again.
        assert(address(c).balance == 0 && balBeforeSecond == b && balAfterWithdraw == 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint a, uint b) public payable {
        require(a > 0);
        require(b > 0);
        require(address(this).balance >= a + b);

        uint t0 = address(this).balance;

        c.deposit{value: a}();
        c.deposit{value: b}();
        uint balAfterDeposits = address(c).balance;

        c.withdrawAll();
        c.withdrawAll();

        assert(
            balAfterDeposits == a + b &&
            address(c).balance == 0 &&
            address(this).balance == t0 + a + b
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount > 0);
        require(amount <= 2**128);
        require(address(this).balance >= amount);

        // Fresh contract: it must start with zero Ether.
        require(address(c).balance == 0);
        uint totalBefore = address(c).balance + address(this).balance;

        c.deposit{value: amount}();
        uint balAfterDeposit = address(c).balance;

        c.withdrawAll();

        assert(
            balAfterDeposit == amount &&
            address(c).balance + address(this).balance == totalBefore &&
            address(c).balance == 0
        );
    }

    receive() external payable {}
}
